const metrics = $json;
const activeConnections = parseInt(metrics.active_connections, 10) || 0;
const waitingLocks = parseInt(metrics.waiting_locks, 10) || 0;
const dbSize = metrics.database_size || 'Bilinmiyor';
const cacheHitRatio = parseFloat(metrics.cache_hit_ratio) || 100.0;
const deadTuples = parseInt(metrics.dead_tuples_total, 10) || 0;
const leads24h = parseInt(metrics.new_leads_24h, 10) || 0;

// Kritik Eşik Analizi
const isConnCritical = activeConnections > 40;
const isLockCritical = waitingLocks > 3;
const isCacheDegraded = cacheHitRatio < 95.0;
const isDeadTuplesHigh = deadTuples > 5000;

const alertRequired = isConnCritical || isLockCritical || isCacheDegraded || isDeadTuplesHigh;

let status = 'HEALTHY';
let warnings = [];
if (isConnCritical) { status = 'WARNING'; warnings.push(`Yüksek bağlantı: ${activeConnections}`); }
if (isLockCritical) { status = 'CRITICAL'; warnings.push(`Bekleyen kilit var: ${waitingLocks}`); }
if (isCacheDegraded) { status = 'WARNING'; warnings.push(`Düşük önbellek isabeti: %${cacheHitRatio}`); }
if (isDeadTuplesHigh) { status = 'WARNING'; warnings.push(`Ölü satır şişmesi: ${deadTuples} dead tuples`); }

return [{
  json: {
    timestamp: new Date().toISOString(),
    status,
    alertRequired,
    activeConnections,
    waitingLocks,
    dbSize,
    cacheHitRatio,
    deadTuples,
    leads24h,
    warningSummary: warnings.join(', ') || 'Metrikler normal sınırlarda.',
    summary: `DB: ${dbSize} | Cache Hit: %${cacheHitRatio} | Aktif: ${activeConnections} | Dead: ${deadTuples}`
  }
}];
